import XCTest
import CryptoKit
@testable import FlagshipCore

/// Pins the Swift port to packages/protocol/test-vectors/org-invite-key/vectors.json (generated by
/// tools/org-invite-key-vectors.ts): the link key's offer key and invite key, the invite's canonical bytes, the read
/// proof and the invite-key signature on the accept, with their negatives.
final class OrgInviteKeyVectorTests: XCTestCase {
    private var V: [String: Any] = [:]

    override func setUpWithError() throws {
        var dir = URL(fileURLWithPath: #filePath).deletingLastPathComponent()
        for _ in 0..<14 {
            let url = dir.appendingPathComponent("packages/protocol/test-vectors/org-invite-key/vectors.json")
            if FileManager.default.fileExists(atPath: url.path) {
                V = try XCTUnwrap(JSONSerialization.jsonObject(with: Data(contentsOf: url)) as? [String: Any])
                return
            }
            dir = dir.deletingLastPathComponent()
        }
        throw XCTSkip("org-invite-key vectors not found above \(#filePath)")
    }

    private func s(_ k: String) -> String { V[k] as! String }
    private func o(_ k: String) -> [String: Any] { V[k] as! [String: Any] }
    private func bytes(_ h: String) -> [UInt8] { PqBin.unhex(h)! }
    private func i64(_ v: Any?) -> Int64 { (v as! NSNumber).int64Value }

    func testDerivesTheOfferKeyAndTheInviteKey() throws {
        let k = try OrgAuthority.inviteKeys(linkKey: bytes(s("linkKeyHex")))
        XCTAssertEqual(PqBin.hex(k.offerKey), s("offerKeyHex"))
        XCTAssertEqual(PqBin.hex(k.secret), s("inviteSecretHex"))
        XCTAssertEqual(k.inviteKeyPub, s("inviteKeyPub"))
        XCTAssertEqual(try OrgAuthority.inviteKeys(linkKey: bytes(s("wrongLinkKeyHex"))).inviteKeyPub, s("wrongInviteKeyPub"))
    }

    func testOpensTheOfferUnderTheOfferKeyOnly() throws {
        let sealed = Data(bytes(o("offer")["sealedHex"] as! String))
        let box = try AES.GCM.SealedBox(combined: sealed)
        let plain = try AES.GCM.open(box, using: SymmetricKey(data: bytes(s("offerKeyHex"))))
        XCTAssertEqual(String(decoding: plain, as: UTF8.self), o("offer")["plaintext"] as! String)
        XCTAssertThrowsError(try AES.GCM.open(box, using: SymmetricKey(data: bytes(s("linkKeyHex")))))
    }

    func testCanonicalBytes() throws {
        let c = o("canonical")
        let inv = (o("invites")["invite"] as! [String: Any])
        let bytesOf = { (b: [UInt8]?) in b.map { String(decoding: $0, as: UTF8.self) } }
        XCTAssertEqual(bytesOf(OrgAuthority.canonicalSeatInvite(inv)), (c["invite"] as! [String: Any])["bytes"] as? String)
        XCTAssertEqual(OrgAuthority.canonicalSeatInvite(inv).map(OrgAuthority.sha256Hex), (c["invite"] as! [String: Any])["sha256"] as? String)
        var old = inv
        old["inviteKeyPub"] = nil
        XCTAssertNil(OrgAuthority.canonicalSeatInvite(old))
        let r = c["read"] as! [String: Any]
        XCTAssertEqual(String(decoding: try OrgAuthority.canonicalInviteRead(orgId: r["orgId"] as! String, seatId: r["seatId"] as! String, issuedAt: i64(r["issuedAt"])), as: UTF8.self),
                       r["bytes"] as! String)
        let w = c["withdraw"] as! [String: Any]
        XCTAssertEqual(String(decoding: try OrgAuthority.canonicalInviteWithdraw(orgId: w["orgId"] as! String, seatId: w["seatId"] as! String,
                                                                                 oarVersion: i64(w["oarVersion"]), issuedAt: i64(w["issuedAt"])), as: UTF8.self),
                       w["bytes"] as! String)
    }

    func testReadProofs() {
        for case let r as [String: Any] in V["reads"] as! [Any] {
            let inv = o("invites")[r["invite"] as! String] as! [String: Any]
            let got = OrgAuthority.verifyInviteRead(orgId: inv["orgId"] as! String, seatId: inv["seatId"] as! String, inviteKeyPub: inv["inviteKeyPub"] as? String,
                                                    issuedAt: i64(r["issuedAt"]), signature: r["signature"] as? String, now: i64(r["now"]))
            XCTAssertEqual(got, r["expect"] as! Bool, r["name"] as! String)
        }
    }

    func testAcceptProofs() {
        for case let a as [String: Any] in V["accepts"] as! [Any] {
            let inv = o("invites")[a["invite"] as! String] as! [String: Any]
            let acc = o("acceptObjects")[a["accept"] as! String] as! [String: Any]
            XCTAssertEqual(OrgAuthority.verifyInviteAccept(invite: inv, accept: acc, signature: a["signature"] as? String), a["expect"] as! Bool, a["name"] as! String)
        }
    }

    /// CryptoKit's Ed25519 signs with fresh randomness, so this signs and checks the result against the vector's key.
    func testSigningMakesProofsTheVerifiersAccept() throws {
        let secret = bytes(s("inviteSecretHex"))
        let r = o("canonical")["read"] as! [String: Any]
        let inv = o("invites")["invite"] as! [String: Any]
        let at = i64(r["issuedAt"])
        let read = try OrgAuthority.inviteReadSignature(secret: secret, orgId: r["orgId"] as! String, seatId: r["seatId"] as! String, issuedAt: at)
        XCTAssertTrue(OrgAuthority.verifyInviteRead(orgId: inv["orgId"] as! String, seatId: inv["seatId"] as! String, inviteKeyPub: s("inviteKeyPub"),
                                                    issuedAt: at, signature: read, now: at))
        let acc = o("acceptObjects")["accept"] as! [String: Any]
        let acceptBytes = Array(((o("canonical")["accept"] as! [String: Any])["bytes"] as! String).utf8)
        let sig = try OrgAuthority.inviteAcceptSignature(secret: secret, acceptBytes: acceptBytes)
        XCTAssertTrue(OrgAuthority.verifyInviteAccept(invite: inv, accept: acc, signature: sig))
    }
}
